package edu.uao.yugioh.model; public class Monstruo extends Carta implements Comparable<Monstruo> { public static final int MIN_ESTADISTICA=0; private int ataque, defensa; private Posicion posicion; public Monstruo(String n,int a,int d){this(n,a,d,Posicion.ATAQUE);} public Monstruo(String n,int a,int d,Posicion p){super(n); if(a<0||d<0)throw new IllegalArgumentException("ATQ y DEF no pueden ser negativos"); ataque=a;defensa=d;posicion=p;} public int getAtaque(){return ataque;} public int getDefensa(){return defensa;} public Posicion getPosicion(){return posicion;} public void setPosicion(Posicion p){posicion=p;} public int estadisticaActiva(){return posicion==Posicion.ATAQUE?ataque:defensa;} @Override public String descripcion(){return getNombre()+" [ATQ "+ataque+" / DEF "+defensa+" / "+posicion+"]";} @Override public int compareTo(Monstruo o){return Integer.compare(ataque,o.ataque);} @Override public String toString(){return descripcion();} }